<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Common\Application\Usecase\Install;

use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Features\Document\Template\Domain\Gateway\TemplateWriteGateway;
use Civi\Lughauth\Features\Document\Template\Domain\Template;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateAttributes;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionWriteGateway;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersionAttributes;

/**
 * Installation step that seeds the "user.delete" mail template used to confirm account
 * deletion requests.
 *
 * This class is invoked once during the initial system installation by InstallUsecase. It
 * creates a Template entity with code "user.delete" bound to the "corporate-mail" theme
 * and appends a TemplateVersion containing the full HTML email body with Handlebars
 * placeholders ({{user.name}}, {{confirm.url}}, {{confirm.expires}}).
 *
 * The template is enabled immediately after creation so that the notification subsystem can
 * dispatch it as soon as a user requests account deletion.
 */
class InstallAskForDeleteTemplate
{
    public function __construct(
        private readonly TemplateWriteGateway $templates,
        private readonly TemplateVersionWriteGateway $versions,
    ) {
    }

    /**
     * Creates and enables the "user.delete" mail template along with its first version
     * containing the account-deletion confirmation email body.
     */
    public function install(): void
    {
        $tpl = new TemplateAttributes();
        $tpl->uid(Random::comb());
        $tpl->code('user.delete');
        $tpl->channel(TemplateChannelOptions::MAIL);
        $tpl->theme('corporate-mail');
        $tpl->enabled(true);
        $created = $this->templates->create(Template::create($tpl));
        $this->templates->update($created, $created->enable());

        $body = <<<'BODY'
<p>Hello {{user.name}},</p>
<p>We received a request to permanently delete your account and all associated data. This action cannot be undone.</p>
<p style="margin:28px 0;text-align:center;">
  <a href="{{confirm.url}}"
     style="display:inline-block;background:#dc2626;color:#ffffff;text-decoration:none;padding:12px 28px;border-radius:6px;font-size:15px;font-weight:bold;">
    Confirm account deletion
  </a>
</p>
<p style="font-size:13px;color:#6b7280;">
  This link expires on <strong>{{confirm.expires}}</strong>.
  If you did not request account deletion, please ignore this email — your account will remain active.
</p>
BODY;

        $ver = new TemplateVersionAttributes();
        $ver->uid(Random::comb());
        $ver->template($created);
        $ver->subject('Confirm your account deletion request');
        $ver->contentHtml($body);
        $this->versions->create(TemplateVersion::create($ver));
    }
}
